mapper.update:
UPDATE articles
SET title = #{article.title},
    content = #{article.content},
    tag = #{article.tag},
    url = #{article.url}
WHERE article_id = #{articleId}

mapper.select:
SELECT EXISTS (
    SELECT 1 FROM article_likes
    WHERE article_id = #{articleId}
      AND user_id    = #{userId}
)

mapper.delete:
DELETE FROM article_likes
WHERE article_id = #{articleId}
  AND user_id    = #{userId}

